    'noPrivateInterface': ['Nenhuma interface IPv4 privada foi detectada pelo backend.', 'No private IPv4 interface was detected by the backend.', 'El backend no detectó ninguna interfaz IPv4 privada.', 'Aucune interface IPv4 privée n’a été détectée par le backend.', 'Das Backend hat keine private IPv4-Schnittstelle erkannt.', 'Il backend non ha rilevato alcuna interfaccia IPv4 privata.'],
    'noDiscoveryProblem': ['Nenhum problema de descoberta foi identificado pelo backend.', 'No discovery problem was identified by the backend.', 'El backend no identificó problemas de descubrimiento.', 'Aucun problème de découverte n’a été identifié par le backend.', 'Das Backend hat kein Erkennungsproblem festgestellt.', 'Il backend non ha identificato problemi di rilevamento.'],
    'ipFallbackSafety': ['O fallback consulta apenas a identidade SteelControl em IPv4 privado/local. Ele não habilita START nem substitui intertravamentos físicos.', 'The fallback only queries SteelControl identity on a private/local IPv4 address. It does not enable START or replace physical interlocks.', 'La alternativa solo consulta la identidad SteelControl en un IPv4 privado/local. No habilita START ni sustituye interbloqueos físicos.', 'La solution de secours interroge uniquement l’identité SteelControl sur une IPv4 privée/locale. Elle n’active pas START et ne remplace pas les interverrouillages physiques.', 'Der Fallback fragt nur die SteelControl-Identität über eine private/lokale IPv4-Adresse ab. Er aktiviert START nicht und ersetzt keine physischen Verriegelungen.', 'Il fallback interroga solo l’identità SteelControl su un IPv4 privato/locale. Non abilita START e non sostituisce gli interblocchi fisici.'],
    'noDiscoveredDevicesFallback': ['Nenhum equipamento respondeu ainda. Tente novamente, abra o diagnóstico ou use o fallback por IP.', 'No device has responded yet. Search again, open diagnostics, or use IP fallback.', 'Aún no respondió ningún equipo. Busque de nuevo, abra el diagnóstico o use la alternativa por IP.', 'Aucun équipement n’a encore répondu. Relancez la recherche, ouvrez le diagnostic ou utilisez le secours par IP.', 'Noch kein Gerät hat geantwortet. Suchen Sie erneut, öffnen Sie die Diagnose oder verwenden Sie den IP-Fallback.', 'Nessun dispositivo ha ancora risposto. Cerca di nuovo, apri la diagnostica o usa il fallback IP.'],
    'discoveryUnknownIssue': ['O backend informou uma condição de rede que precisa ser verificada.', 'The backend reported a network condition that needs checking.', 'El backend informó una condición de red que debe verificarse.', 'Le backend a signalé une condition réseau à vérifier.', 'Das Backend hat eine Netzwerkbedingung gemeldet, die geprüft werden muss.', 'Il backend ha segnalato una condizione di rete da verificare.'],
    'discoveryIssueDisabled': ['A descoberta está desativada no backend. Verifique DISCOVERY_ENABLED.', 'Discovery is disabled in the backend. Check DISCOVERY_ENABLED.', 'El descubrimiento está desactivado en el backend. Revise DISCOVERY_ENABLED.', 'La découverte est désactivée dans le backend. Vérifiez DISCOVERY_ENABLED.', 'Die Erkennung ist im Backend deaktiviert. Prüfen Sie DISCOVERY_ENABLED.', 'Il rilevamento è disattivato nel backend. Verifica DISCOVERY_ENABLED.'],
    'discoveryIssueUdpNotReady': ['O listener UDP ainda não está pronto. Reinicie o backend e confira a porta de descoberta.', 'The UDP listener is not ready yet. Restart the backend and check the discovery port.', 'El listener UDP aún no está listo. Reinicie el backend y revise el puerto de descubrimiento.', 'Le listener UDP n’est pas encore prêt. Redémarrez le backend et vérifiez le port de découverte.', 'Der UDP-Listener ist noch nicht bereit. Starten Sie das Backend neu und prüfen Sie den Erkennungsport.', 'Il listener UDP non è ancora pronto. Riavvia il backend e controlla la porta di rilevamento.'],
    'discoveryIssueNoInterface': ['O backend não encontrou uma interface IPv4 privada ativa. Confira Wi-Fi/Ethernet.', 'The backend found no active private IPv4 interface. Check Wi-Fi/Ethernet.', 'El backend no encontró una interfaz IPv4 privada activa. Revise Wi-Fi/Ethernet.', 'Le backend n’a trouvé aucune interface IPv4 privée active. Vérifiez le Wi-Fi/Ethernet.', 'Das Backend hat keine aktive private IPv4-Schnittstelle gefunden. Prüfen Sie WLAN/Ethernet.', 'Il backend non ha trovato un’interfaccia IPv4 privata attiva. Controlla Wi-Fi/Ethernet.'],
    'discoveryIssueNoResponse': ['Nenhum dispositivo respondeu à última busca. Verifique firewall UDP, isolamento do Wi-Fi, VLAN/sub-rede e o firmware do equipamento.', 'No device answered the last search. Check the UDP firewall, Wi-Fi client isolation, VLAN/subnet, and device firmware.', 'Ningún dispositivo respondió a la última búsqueda. Revise firewall UDP, aislamiento Wi-Fi, VLAN/subred y firmware.', 'Aucun appareil n’a répondu à la dernière recherche. Vérifiez le pare-feu UDP, l’isolation Wi-Fi, le VLAN/sous-réseau et le firmware.', 'Kein Gerät hat auf die letzte Suche geantwortet. Prüfen Sie UDP-Firewall, WLAN-Client-Isolation, VLAN/Subnetz und Firmware.', 'Nessun dispositivo ha risposto all’ultima ricerca. Controlla firewall UDP, isolamento Wi-Fi, VLAN/sottorete e firmware.'],
    'discoveryIssueMultipleAdapters': ['Há várias interfaces de rede ativas. VPN, Docker ou adaptadores virtuais podem interferir; o SteelControl tenta os broadcasts detectados.', 'Several network interfaces are active. VPN, Docker, or virtual adapters may interfere; SteelControl tries the detected broadcasts.', 'Hay varias interfaces de red activas. VPN, Docker o adaptadores virtuales pueden interferir; SteelControl prueba los broadcasts detectados.', 'Plusieurs interfaces réseau sont actives. VPN, Docker ou des adaptateurs virtuels peuvent interférer ; SteelControl essaie les diffusions détectées.', 'Mehrere Netzwerkschnittstellen sind aktiv. VPN, Docker oder virtuelle Adapter können stören; SteelControl versucht die erkannten Broadcasts.', 'Sono attive più interfacce di rete. VPN, Docker o adattatori virtuali possono interferire; SteelControl prova i broadcast rilevati.'],
    'discoveryIssueUdpError': ['O backend registrou uma falha ao enviar a busca UDP. Confira a porta e o firewall.', 'The backend recorded a failure while sending the UDP search. Check the port and firewall.', 'El backend registró un fallo al enviar la búsqueda UDP. Revise el puerto y el firewall.', 'Le backend a enregistré un échec lors de l’envoi de la recherche UDP. Vérifiez le port et le pare-feu.', 'Das Backend hat beim Senden der UDP-Suche einen Fehler registriert. Prüfen Sie Port und Firewall.', 'Il backend ha registrato un errore durante l’invio della ricerca UDP. Controlla porta e firewall.'],
    'discoveryIssueIpFailed': ['A última tentativa pelo IP falhou. Confirme IP, porta, mesma rede e endpoint SteelControl do dispositivo.', 'The last IP attempt failed. Confirm the IP, port, same network, and the device SteelControl endpoint.', 'El último intento por IP falló. Confirme IP, puerto, misma red y endpoint SteelControl del dispositivo.', 'La dernière tentative par IP a échoué. Vérifiez l’IP, le port, le même réseau et l’endpoint SteelControl de l’appareil.', 'Der letzte IP-Versuch ist fehlgeschlagen. Prüfen Sie IP, Port, dasselbe Netzwerk und den SteelControl-Endpunkt des Geräts.', 'L’ultimo tentativo tramite IP è fallito. Verifica IP, porta, stessa rete ed endpoint SteelControl del dispositivo.'],
